const PLAN_CHANGE_RE = /(^|[^а-яёa-z])(что\s+изменил[а-яё]*|изменил(ось|ись|ся|ась)|изменени[а-яё]+|с\s+прошл(ым|ого)\s+(отч[её]т|период|раз)[а-яё]*|динамик[а-яё]*|что\s+нового\s+(у|на|в))([^а-яёa-z]|$)/i;
